import math
    import random
    import time

    LANGUAGE_WRAPPER = 'For each integer n in the range [{n_start}, {n_end}], let A(n) be the set of ordered pairs (i, j) with 1 ≤ i < j ≤ n and i divides j, and let T(n) be the set of ordered triples (i, j, k) with 1 ≤ i < j < k ≤ n and i divides j and j divides k. Consider real variables x_1, x_2, ..., x_n in [0, 1] constrained by the equality Σ_{i=1}^n x_i = floor(n/3) + {delta}. Define\n\nd(n) = max over x_i ∈ [0,1], Σ x_i = floor(n/3) + {delta} of [ Σ_{i=1}^n x_i^{p} − {lambda} · Σ_{(i,j)∈A(n)} (x_i x_j)^{q} − {mu} · Σ_{(i,j,k)∈T(n)} (x_i x_j x_k)^{q} ].\n\nCompute the exact value of S = Σ_{n={n_start}}^{n_end} d(n).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a nontrivial range for n
n_start = rng.randint(60, 220)
span = rng.randint(150, 300)
n_end = n_start + span
# Choose exponents ensuring convexity of Σ x_i^p and superlinear interactions
p = rng.choice([3, 4, 5])
q = rng.choice([2, 3])
# Penalty coefficients (not trivial)
lam_choices = [0.5, 0.75, 1.0, 1.25, 1.5, rng.randint(2,5)/rng.randint(6,13)]
mu_choices = [0.3, 0.4, 0.6, 0.8, 1.0, rng.randint(2,7)/rng.randint(8,15)]
lam = rng.choice(lam_choices)
mu = rng.choice(mu_choices)
# Fractional addition to floor(n/3): keep small to guarantee feasibility and non-integer sum
# Ensure delta in (0.05, 0.49) for difficulty and fractional leftover
delta = round(rng.uniform(0.08, 0.48), 3)
# Sanity check: ensure feasibility holds for the entire range (s(n) <= ceil(n/2))
# s(n) = floor(n/3) + delta
for n in [n_start, (n_start + n_end)//2, n_end]:
    s = (n // 3) + delta
    cap = (n + 1) // 2  # ceil(n/2)
    if s > cap + 1e-12:
        # Rare, but retry if constraint fails
        return generator(rng)
return {
    'n_start': n_start,
    'n_end': n_end,
    'p': p,
    'q': q,
    'lambda': lam,
    'mu': mu,
    'delta': delta
}

    def verifier(assign):
# Validate presence of required keys
required = ['n_start', 'n_end', 'p', 'q', 'lambda', 'mu', 'delta']
for k in required:
    if k not in assign:
        # Missing parameter
        return (False, None)
n_start = assign['n_start']
n_end = assign['n_end']
p = assign['p']
q = assign['q']
lam = assign['lambda']
mu = assign['mu']
delta = assign['delta']
# Basic type/domain checks
if not (isinstance(n_start, int) and isinstance(n_end, int) and n_start >= 3 and n_end >= n_start):
    return (False, None)
if not (isinstance(p, int) and p >= 3):
    return (False, None)
if not (isinstance(q, int) and q >= 2):
    return (False, None)
if not (isinstance(delta, (int, float))):
    return (False, None)
if not (0.0 < delta < 0.5):
    return (False, None)
if not (isinstance(lam, (int, float)) and isinstance(mu, (int, float))):
    return (False, None)
# Feasibility: for each n, s(n) = floor(n/3) + delta must be <= ceil(n/2)
# This guarantees the optimizer can avoid all pair/triple penalties by concentrating on the upper half.
for n in (n_start, (n_start + n_end)//2, n_end):
    s = (n // 3) + float(delta)
    cap = (n + 1) // 2  # ceil(n/2)
    if s > cap + 1e-12:
        # If this fails, our closed-form no-penalty solution would not apply
        return (False, None)
# Compute the exact sum S = sum_{n=n_start}^{n_end} d(n)
# With s(n) <= ceil(n/2), we can place all mass on an antichain (e.g., indices > n/2), so all penalties vanish.
# Then d(n) reduces to maximizing sum x_i^p given sum x_i = s, 0 <= x_i <= 1.
# For p > 1 this is achieved by k ones and one fractional remainder r.
total = 0.0
for n in range(n_start, n_end + 1):
    s = (n // 3) + float(delta)
    k = int(s)  # floor(s)
    r = s - k
    d_n = k + (r ** p)
    total += d_n
return (True, total)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

